import MaterialIcons from "@expo/vector-icons/MaterialIcons";
import { useLocalSearchParams, router } from "expo-router";
import { useEffect, useState } from "react";
import { ActivityIndicator, Alert, ScrollView, StyleSheet, Text, TextInput, TouchableOpacity, View } from "react-native";

import { ScreenContainer } from "@/components/screen-container";
import { djangoApi } from "@/lib/django-api";

type Item = { id:number; product_id:number; name:string; sku:string; quantity:number; unit_price:string; color:string; size:string; total:string; image?:string|null };
type Details = { id:number; order_id:number; order_number:string; parent_order_number:string; status:string; subtotal:string; shipping_fee:string; discount:string; total:string; commission:string; vendor_net:string; currency:string; customer:{name:string;phone:string}; shipping_address:Record<string, any>; payment_method:string; payment_status:string; shipment:{carrier:string;tracking_number:string;status:string}; items:Item[] };

const statuses = ["pending","confirmed","processing","shipped","delivered","cancelled"];
const shipmentStatuses = ["pending","ready","shipped","in_transit","delivered","returned","cancelled"];
const labels:Record<string,string> = {pending:"جديد",confirmed:"مؤكد",processing:"تجهيز",shipped:"تم الشحن",delivered:"تم التسليم",cancelled:"ملغى",ready:"جاهز للشحن",in_transit:"في الطريق",returned:"مرتجع"};

export default function VendorOrderDetail(){
  const { id } = useLocalSearchParams<{id:string}>();
  const [data,setData] = useState<Details|null>(null);
  const [loading,setLoading] = useState(true);
  const [busy,setBusy] = useState(false);
  const [carrier,setCarrier] = useState("");
  const [tracking,setTracking] = useState("");

  async function load(){ try{ const result=await djangoApi<Details>(`/api/orders/${id}/vendor_detail/`); setData(result); setCarrier(result.shipment?.carrier??""); setTracking(result.shipment?.tracking_number??""); }catch(error){Alert.alert("تعذر تحميل الطلب",error instanceof Error?error.message:"حاولي مجددًا")}finally{setLoading(false)} }
  useEffect(()=>{ if(id) load(); },[id]);
  async function updateStatus(status:string){ if(!data)return; setBusy(true); try{ await djangoApi(`/api/orders/${data.order_id}/update_status/`,{method:"POST",body:JSON.stringify({status})}); await load(); }catch(error){Alert.alert("تعذر تحديث الحالة",error instanceof Error?error.message:"حاولي مجددًا")}finally{setBusy(false)} }
  async function saveShipment(status=data?.shipment.status||"pending"){ if(!data)return; setBusy(true); try{ const result=await djangoApi<Details>("/api/orders/update_shipment/",{method:"POST",body:JSON.stringify({vendor_order_id:data.id,carrier,tracking_number:tracking,status})}); setData(result); Alert.alert("تم الحفظ","تم تحديث بيانات الشحن بنجاح."); }catch(error){Alert.alert("تعذر تحديث الشحن",error instanceof Error?error.message:"حاولي مجددًا")}finally{setBusy(false)} }
  if(loading)return <ScreenContainer><View style={styles.center}><ActivityIndicator color="#E60023"/></View></ScreenContainer>;
  if(!data)return <ScreenContainer><View style={styles.center}><Text>الطلب غير متاح.</Text></View></ScreenContainer>;
  const address=data.shipping_address||{};
  return <ScreenContainer className="bg-[#F6F7F9]" edges={["top","bottom","left","right"]}>
    <View style={styles.header}><TouchableOpacity onPress={()=>router.back()}><MaterialIcons name="arrow-forward" size={23} color="#111"/></TouchableOpacity><View style={styles.headCopy}><Text style={styles.title}>#{data.order_number}</Text><Text style={styles.sub}>طلب العميل · {data.parent_order_number}</Text></View><TouchableOpacity onPress={()=>router.push(`/vendor/messages/${data.id}` as never)} style={styles.chat}><MaterialIcons name="chat" size={18} color="#FFF"/></TouchableOpacity></View>
    <ScrollView contentContainerStyle={styles.content}>
      <View style={styles.hero}><View style={styles.heroIcon}><MaterialIcons name="shopping-bag" size={24} color="#FFF"/></View><View style={styles.heroCopy}><Text style={styles.heroTotal}>{data.total} {data.currency}</Text><Text style={styles.heroHint}>{labels[data.status]||data.status} · صافي التاجر {data.vendor_net}</Text></View></View>
      <Card title="العميل والعنوان" icon="person-outline"><Text style={styles.strong}>{data.customer.name}</Text><Text style={styles.muted}>{data.customer.phone}</Text><Text style={styles.address}>{address.title||"عنوان التوصيل"} · {address.city_name||address.city||""}</Text><Text style={styles.muted}>{address.district||""} {address.street?`· ${address.street}`:""}</Text></Card>
      <Card title="المنتجات" icon="inventory-2">{data.items.map(item=><View style={styles.item} key={item.id}><View style={styles.itemTotal}><Text style={styles.strongSmall}>{item.total} {data.currency}</Text><Text style={styles.muted}>× {item.quantity}</Text></View><View style={styles.itemCopy}><Text style={styles.itemName}>{item.name}</Text><Text style={styles.muted}>{item.sku}{item.color?` · ${item.color}`:""}{item.size?` · ${item.size}`:""}</Text></View></View>)}</Card>
      <Card title="حالة الطلب" icon="timeline"><ScrollView horizontal inverted showsHorizontalScrollIndicator={false} contentContainerStyle={styles.chips}>{statuses.map(s=><TouchableOpacity key={s} disabled={busy} onPress={()=>updateStatus(s)} style={[styles.chip,data.status===s&&styles.chipActive]}><Text style={[styles.chipText,data.status===s&&styles.chipActiveText]}>{labels[s]}</Text></TouchableOpacity>)}</ScrollView></Card>
      <Card title="الشحن والتتبع" icon="local-shipping"><Text style={styles.label}>شركة الشحن</Text><TextInput value={carrier} onChangeText={setCarrier} placeholder="مثال: أرامكس / مندوب المتجر" style={styles.input} textAlign="right"/><Text style={styles.label}>رقم التتبع</Text><TextInput value={tracking} onChangeText={setTracking} placeholder="رقم التتبع" style={styles.input} textAlign="left" autoCapitalize="none"/><Text style={styles.label}>حالة الشحنة</Text><ScrollView horizontal inverted showsHorizontalScrollIndicator={false} contentContainerStyle={styles.chips}>{shipmentStatuses.map(s=><TouchableOpacity key={s} onPress={()=>saveShipment(s)} disabled={busy} style={[styles.chip,data.shipment.status===s&&styles.chipActive]}><Text style={[styles.chipText,data.shipment.status===s&&styles.chipActiveText]}>{labels[s]||s}</Text></TouchableOpacity>)}</ScrollView><TouchableOpacity style={styles.primary} onPress={()=>saveShipment()} disabled={busy}><MaterialIcons name="save" size={18} color="#FFF"/><Text style={styles.primaryText}>{busy?"جارٍ الحفظ...":"حفظ بيانات الشحن"}</Text></TouchableOpacity></Card>
      <View style={styles.totalCard}><Row label="المجموع" value={`${data.subtotal} ${data.currency}`}/><Row label="الشحن" value={`${data.shipping_fee} ${data.currency}`}/><Row label="الخصم" value={`${data.discount} ${data.currency}`}/><Row label="عمولة المنصة" value={`${data.commission} ${data.currency}`}/><View style={styles.sep}/><Row label="صافي التاجر" value={`${data.vendor_net} ${data.currency}`} strong/></View>
    </ScrollView>
  </ScreenContainer>
}
function Card({title,icon,children}:{title:string;icon:string;children:React.ReactNode}){return <View style={styles.card}><View style={styles.cardHead}><View style={styles.cardIcon}><MaterialIcons name={icon as any} size={17} color="#111"/></View><Text style={styles.cardTitle}>{title}</Text></View>{children}</View>}
function Row({label,value,strong=false}:{label:string;value:string;strong?:boolean}){return <View style={styles.row}><Text style={[styles.rowValue,strong&&styles.rowStrong]}>{value}</Text><Text style={[styles.rowLabel,strong&&styles.rowStrongLabel]}>{label}</Text></View>}
const styles=StyleSheet.create({header:{height:62,backgroundColor:"#FFF",paddingHorizontal:14,flexDirection:"row-reverse",alignItems:"center",gap:9,borderBottomWidth:1,borderColor:"#EEE"},headCopy:{flex:1,alignItems:"flex-end"},title:{fontSize:15,fontWeight:"900",color:"#111"},sub:{fontSize:9,color:"#999",marginTop:2},chat:{width:38,height:38,borderRadius:12,backgroundColor:"#111",alignItems:"center",justifyContent:"center"},content:{padding:12,paddingBottom:120,maxWidth:900,width:"100%",alignSelf:"center"},hero:{backgroundColor:"#111",borderRadius:18,padding:18,flexDirection:"row-reverse",alignItems:"center",gap:12,marginBottom:10},heroIcon:{width:44,height:44,borderRadius:14,backgroundColor:"#E60023",alignItems:"center",justifyContent:"center"},heroCopy:{flex:1,alignItems:"flex-end"},heroTotal:{color:"#FFF",fontSize:25,fontWeight:"900"},heroHint:{color:"#BDBDBD",fontSize:10,marginTop:3,textAlign:"right"},card:{backgroundColor:"#FFF",borderRadius:14,padding:14,marginBottom:10,borderWidth:1,borderColor:"#ECECEC"},cardHead:{flexDirection:"row-reverse",alignItems:"center",gap:8,marginBottom:13},cardIcon:{width:30,height:30,borderRadius:9,backgroundColor:"#F2F3F5",alignItems:"center",justifyContent:"center"},cardTitle:{fontSize:14,fontWeight:"900",color:"#111"},strong:{fontSize:14,fontWeight:"900",color:"#111",textAlign:"right"},muted:{fontSize:11,color:"#777",textAlign:"right",marginTop:3},address:{fontSize:12,color:"#333",fontWeight:"700",textAlign:"right",marginTop:9},item:{flexDirection:"row-reverse",justifyContent:"space-between",gap:10,paddingVertical:10,borderBottomWidth:1,borderColor:"#F1F1F1"},itemCopy:{flex:1,alignItems:"flex-end"},itemName:{fontSize:12,fontWeight:"800",color:"#222",textAlign:"right"},itemTotal:{alignItems:"flex-start",minWidth:80},strongSmall:{fontSize:12,fontWeight:"900",color:"#111"},chips:{gap:7,paddingBottom:4},chip:{paddingHorizontal:12,paddingVertical:8,borderWidth:1,borderColor:"#DDD",borderRadius:20,backgroundColor:"#FFF"},chipActive:{backgroundColor:"#111",borderColor:"#111"},chipText:{fontSize:10,color:"#666",fontWeight:"800"},chipActiveText:{color:"#FFF"},label:{fontSize:11,fontWeight:"800",color:"#555",textAlign:"right",marginBottom:6,marginTop:8},input:{height:44,borderWidth:1,borderColor:"#E4E4E4",backgroundColor:"#F8F9FA",borderRadius:10,paddingHorizontal:12,fontSize:13,color:"#111"},primary:{marginTop:12,height:44,borderRadius:22,backgroundColor:"#E60023",flexDirection:"row-reverse",alignItems:"center",justifyContent:"center",gap:7},primaryText:{color:"#FFF",fontSize:12,fontWeight:"900"},totalCard:{backgroundColor:"#FFF",borderRadius:14,padding:15,marginBottom:20},row:{flexDirection:"row-reverse",justifyContent:"space-between",paddingVertical:6},rowLabel:{fontSize:12,color:"#666"},rowValue:{fontSize:12,fontWeight:"700",color:"#333"},rowStrong:{fontSize:17,color:"#E60023",fontWeight:"900"},rowStrongLabel:{fontWeight:"900",color:"#111"},sep:{height:1,backgroundColor:"#EEE",marginVertical:6},center:{flex:1,alignItems:"center",justifyContent:"center"}});
